# Chinese translations for trick names/descriptions, keyed by RT id.
td = {
    "RT_VISIBLE_COLLISION": {"name": "忽略可见碰撞", "desc": "允许忽略那些并不会真正阻挡林克行走、攀爬或撞击的可见障碍与物体，且无需穿模。\n\n最典型的例子是倒着穿过卡卡利科大门、以成年身份从合作社爬进因帕之家后侧，以及隔着方块、冰与墙壁击中锈蚀开关或巨石。\n\n此 trick 仅适用于完成动作本身很简单的情形；仅能从特定角度完成的、以及各种穿模（包括用跳劈把林克的判定框卡进巨石里）都不属于此 trick。"},
    "RT_GROTTOS_WITHOUT_AGONY": {"name": "无需痛苦之石进入隐藏洞穴", "desc": "允许在没有痛苦之石的情况下进入隐藏洞穴。"},
    "RT_FEWER_TUNIC_REQUIREMENTS": {"name": "更少的衣服要求", "desc": "通常，逻辑上唯一预期你无需哥隆衣服就能穿越的热区是死亡火山口，且不会预期你无需佐拉衣服就能穿越水下区域。\n\n开启此 trick 后，预期你可以穿越除中央石柱外的任何水下区域、除沃尔瓦吉亚与火之神殿的方块升降室外任何热区，且逻辑上穿越火山口所需的生命值也会降低。"},
    "RT_UNINTUITIVE_JUMPS": {"name": "反直觉跳跃", "desc": "许多窗台可以通过特定的跳跃越过，且无需任何道具即可轻松完成。\n这包括从高处跳下以在没有鳞片的情况下潜得更深，\n不过此 trick 不涵盖水之殿的龙之房。"},
    "RT_FIRE_RINGS": {"name": "火圈", "desc": "当林克因受到伤害而处于无敌状态时，可以冲入火圈，从而与圈内某些物体（例如大宝箱）互动。"},
    "RT_DAMAGE_BOOST_SIMPLE": {"name": "简易伤害冲刺", "desc": "允许利用伤害冲刺来到达更远的位置。可与“简易悬停冲刺”组合以抵达极远的距离。"},
    "RT_HOVER_BOOST_SIMPLE": {"name": "简易悬停冲刺", "desc": "允许在林克高速移动时穿上悬停靴以延长移动距离，通常是在被击退之后。可与“简易伤害冲刺”组合以发挥更大作用。"},
    "RT_BOMBCHU_BEEHIVES": {"name": "炸弹袋炸蜂巢", "desc": "允许用炸弹袋炸开蜂巢。"},
    "RT_HOOKSHOT_LADDERS": {"name": "钩锁梯子", "desc": "可以跳过攀爬：从正确的距离和角度用钩锁勾住梯子的顶端即可省略攀爬。\n某些梯子比其他更难，少数则不可能。\n用同样方式钩锁可攀爬的墙壁不属于 trick，因为很容易找到一个能正确抓住窗台的角度。"},
    "RT_BLUE_FIRE_MUD_WALLS": {"name": "红冰之外的蓝火", "desc": "使用蓝火来破坏泥墙、引爆炸弹花，并破坏通往多东戈之王的地板。\n不适用于大师任务版 Dead Hand 的炸弹花。\n用蓝火引爆炸弹花以阻止滚动的哥隆，还需要“用丁斯的火焰阻止哥隆林克”。\n用蓝火箭破坏多东戈之王房间里的地板，还需要“多东戈洞窟击碎 Boss 大厅地板”。"},
    "RT_OPEN_UNDERWATER_CHEST": {"name": "开启水下宝箱", "desc": "穿着铁靴并用钩锁勾住宝箱，即可开启水下宝箱。"},
    "RT_DISTANT_BOULDER_COLLISION": {"name": "远处巨石碰撞", "desc": "在远处时巨石碰撞会被关闭，使抛射物可以穿过它们。"},
    "RT_ITEM_EXTENSION": {"name": "道具延伸", "desc": "略微延长钩锁、弓或弹弓等抛射物的射程。也允许让抛射物穿过碰撞体。用于：\n- 用钩锁穿越格鲁德山谷\n- 在炸弹花旁取回死亡火山口黄金骷髅\n- 在精神神殿大镜子房用弓、弹弓或钩锁隔着墙击中开关\n- 在精神试炼用弓或弹弓隔着墙击中开关\n- 在大师任务版 Shadow 神殿用弓或弹弓隔着门击中开关"},
    "RT_BIG_SKULLTULA_PAUSE_LIFT": {"name": "用暂停抬起大骷髅", "desc": "当大骷髅微微向上浮动时暂停，会把它稍微抬起，\n最终无需任何道具即可通过。"},
    "RT_GROUND_JUMP": {"name": "地面跳跃", "desc": "允许需要地面跳跃。"},
    "RT_GROUND_JUMP_HARD": {"name": "高难度地面跳跃", "desc": "允许需要一定精度的地面跳跃（除起跳准备之外），\n例如需要借助跳劈获得额外高度，或穿着悬停靴边跑边跳。"},
    "RT_SLIDE_JUMP": {"name": "滑行跳跃", "desc": "在冰面上侧滑的同时向前跑，可以用来跳上平台。"},
    "RT_KF_ADULT_GS": {"name": "成年科克里森林黄金骷髅（悬停靴）", "desc": "可以不用钩锁，借助某条树根使用悬停靴来获得。"},
    "RT_LW_BRIDGE": {"name": "成年空手跳上迷失森林桥", "desc": "通过非常精准的操作，成年林克无需长钩锁、悬停靴或魔法豆，也能跳上那座桥。"},
    "RT_LW_MIDO_BACKFLIP": {"name": "成年后空翻越过米多", "desc": "通过特定的位置与角度，你可以后空翻越过米多。"},
    "RT_LOST_WOOD_NAVI_DIVE": {"name": "迷失森林 Navi 潜水", "desc": "需要德古木棒或科克里之剑，才能与 Navi 一起潜水进入佐拉之河。"},
    "RT_LW_GS_BEAN": {"name": "迷失森林成年黄金骷髅（无魔法豆）", "desc": "只要你能先想办法杀死骷髅，就可以用精准的钩锁取走令牌。可以用长钩锁、弓、炸弹袋或丁斯的火焰将其杀死。"},
    "RT_HC_STORMS_GS": {"name": "海拉鲁城堡暴风雨洞穴黄金骷髅（仅回力标）", "desc": "通过精准的投掷，仅用回力标就能杀死骷髅并取走令牌，无需先炸开墙壁。"},
    "RT_HF_BIG_POE_WITHOUT_EPONA": {"name": "无需 Epona 的大 Poe", "desc": "大 Poe 有可能在没有 Epona 的情况下出现，你只需用弓就能快速射杀它们。"},
    "RT_KAK_TOWER_GS": {"name": "卡卡利科塔黄金骷髅（跳劈）", "desc": "尽可能高地爬塔，但别碰到黄金骷髅，然后松手立即跳劈。只要在梯子上尽量低的位置跳劈仍能击中骷髅，此 trick 就可以做到不掉血。"},
    "RT_KAK_CHILD_WINDMILL_POH": {"name": "童年风车爱心（精准跳劈）", "desc": "童年时，借助与旋转平台同步的精准跳劈，可以从下方跳上旋转平台。"},
    "RT_KAK_ROOFTOP_GS": {"name": "卡卡利科屋顶黄金骷髅（悬停靴）", "desc": "从因帕之家入口处穿上悬停靴，走到骷髅屋的屋顶。从那里，用精准的悬停靴后退走接后空翻，可以到达村庄一侧上方的小山丘。然后再从那里悬停到因帕的屋顶，杀死骷髅并后空翻落入令牌。"},
    "RT_GY_POH": {"name": "墓地独立爱心（回力标）", "desc": "通过精准的位移操作，让回力标在返回路径上与爱心互动，即可获得爱心碎片。"},
    "RT_GY_CHILD_DAMPE_RACE_POH": {"name": "童年第二次 Dampé 赛跑", "desc": "童年时可以在一分钟内完成第二次 Dampé 赛跑，但时间限制非常严格。"},
    "RT_GY_SHADOW_FIRE_ARROWS": {"name": "用火之箭进入 Shadow 神殿", "desc": "仅用火之箭就能点燃所有火把以打开 Shadow 神殿入口是可能的，但你必须非常迅速、精准，并在射击时机上讲究策略。"},
    "RT_DMT_SHIELDLESS_CLIMB": {"name": "童年死亡山脉小径无盾攀爬", "desc": "童年林克可以通过后退走，或干脆承受伤害，在没有海拉鲁之盾或娜茹之爱的情况下越过喷发处到达死亡山脉山顶。"},
    "RT_DMT_SOIL_GS": {"name": "死亡山脉小径土壤黄金骷髅（不破坏巨石）", "desc": "即便巨石仍挡在入口，虫子也会进入松软的土壤。然后，通过精准的位移操作，让回力标在返回路径上与其互动，即可杀死黄金骷髅并取走令牌。"},
    "RT_DMT_BOMBABLE": {"name": "童年死亡山脉小径宝箱（力量）", "desc": "童年林克可以用附近的炸弹花炸开墙壁。你必须带着炸弹花后退走，然后迅速把它朝墙壁扔过去。"},
    "RT_DMT_HOVERS_LOWER_GS": {"name": "死亡山脉小径下红石黄金骷髅（悬停靴）", "desc": "杀死骷髅后，无需破坏岩石，用悬停靴后空翻落到它身上即可取走令牌。先用悬停靴站上附近的栅栏，再从那里去取黄金骷髅令牌。"},
    "RT_DMT_BEAN_LOWER_GS": {"name": "死亡山脉小径下红石黄金骷髅（魔法豆）", "desc": "杀死骷髅后，无需破坏岩石，在魔法豆植物处起跳，于空中凭借精准的时机与定位跳落其上即可取走令牌。"},
    "RT_DMT_JS_LOWER_GS": {"name": "死亡山脉小径下红石黄金骷髅（跳劈）", "desc": "杀死骷髅后，无需破坏岩石，从精准角度跳劈即可取走令牌。"},
    "RT_DMT_CLIMB_HOVERS": {"name": "死亡山脉小径攀爬（悬停靴）", "desc": "可以用悬停靴绕开需要破坏的巨石，从而通往死亡山脉山顶。"},
    "RT_DMT_UPPER_GS": {"name": "死亡山脉小径上红石黄金骷髅（后空翻）", "desc": "杀死骷髅后，从正确角度后空翻撞入岩石即可取走令牌。"},
    "RT_GC_POT": {"name": "哥隆之城旋转壶爱心（炸弹袋）", "desc": "可以用炸弹袋停下旋转的壶，但要让它停下相当讲究。"},
    "RT_GC_POT_STRENGTH": {"name": "哥隆之城旋转壶爱心（力量）", "desc": "允许仅用炸弹花停下哥隆之城的旋转壶，以力量代替背包里的爆炸物。"},
    "RT_GC_ROLLING_STRENGTH": {"name": "童年推滚哥隆（热杆哥隆，力量）", "desc": "在楼梯上或 Medigoron 附近使用炸弹花。时机很紧，尤其是不后退走时。"},
    "RT_GC_LEFTMOST": {"name": "哥隆之城迷宫左宝箱（悬停靴）", "desc": "从木箱顶端开始精准后退走，以精准计时的后空翻结束，即可到达这个宝箱，无需铁锤或银护腕。"},
    "RT_GC_GROTTO": {"name": "哥隆之城洞穴（受伤时用钩锁）", "desc": "在承受熔岩地板伤害的过程中迅速使用钩锁，即可到达哥隆之城洞穴。"},
    "RT_GC_LINK_GORON_DINS": {"name": "用丁斯的火焰阻止哥隆林克", "desc": "时机相当别扭。"},
    "RT_DMC_HOVER_BEAN_POH": {"name": "火山口魔法豆爱心（悬停靴）", "desc": "从哥隆之城附近桥的基座处悬停，走上那道极陡的斜坡。"},
    "RT_DMC_BOLERO_JUMP": {"name": "死亡山脉火山口跳向波雷洛", "desc": "成年时，在速度与位置都恰到好处时用盾牌丢出一个壶，壶会把你多推那么一点距离，正好让你跳过桥上的缺口。"},
    "RT_DMC_BOULDER_JS": {"name": "死亡山脉火山口上→下（铁锤）", "desc": "用铁锤，可以在同一次跳跃中跳劈岩石两次，从而在坠入熔岩前将其破坏。"},
    "RT_DMC_BOULDER_SKIP": {"name": "死亡山脉火山口上→下巨石跳过", "desc": "成年时，通过小心定位，你可以跳上巨石所在的窗台，然后反复抓取窗台挪移到可攀爬的窗台。此 trick 取代了“死亡山脉火山口上→下（铁锤）”。"},
    "RT_ZR_LOWER": {"name": "佐拉之河下独立爱心（成年空手）", "desc": "成年林克可以通过精准跳跃到达这个爱心，无需悬停靴。"},
    "RT_ZR_UPPER": {"name": "佐拉之河上独立爱心（成年空手）", "desc": "成年林克可以通过精准跳跃到达这个爱心，无需悬停靴。"},
    "RT_ZR_HOVERS": {"name": "佐拉领域入口（悬停靴）", "desc": "成年时可以悬停到瀑布后方。"},
    "RT_ZR_CUCCO": {"name": "佐拉领域入口（小鸡）", "desc": "童年时可以带着小鸡飞到瀑布后方。"},
    "RT_ZD_KING_ZORA_SKIP": {"name": "成年空手跳过佐拉之王", "desc": "成年时通过精准跳跃，可以从正面跳上佐拉之王旁的栅栏，从而进入佐拉之泉。"},
    "RT_ZD_GS": {"name": "佐拉领域黄金骷髅（无额外道具）", "desc": "精准的跳劈可以杀死骷髅并回弹到冰冻瀑布顶端。要杀死它，逻辑上通常保证你有钩锁、弓或魔法之一。"},
    "RT_ZF_GREAT_FAIRY_WITHOUT_EXPLOSIVES": {"name": "佐拉之泉大妖精（无爆炸物）", "desc": "可以用银护腕搬起银色岩石，并用铁锤砸碎它下方的岩石，从而抓取洞口边缘、越过可破坏的墙（铁锤无法直接破坏那面墙）。"},
    "RT_LH_LAB_WALL_GS": {"name": "海拉鲁湖研究所墙黄金骷髅（跳劈）", "desc": "实际取走令牌的那下跳劈需要一定精准度。"},
    "RT_LH_LAB_DIVING": {"name": "海拉鲁湖研究所潜水（无黄金鳞片）", "desc": "在钩锁水下木箱的过程中脱下铁靴。"},
    "RT_LH_WATER_HOOKSHOT": {"name": "无铁靴用水之殿入口（钩锁）", "desc": "在用水之殿入口改用黄金鳞片而非铁靴时，通常会用长钩锁来击中开关并开门。但站在特定位置，仅用钩锁的射程就能击中开关。"},
    "RT_GV_CRATE_HOVERS": {"name": "格鲁德山谷木箱爱心（成年悬停靴）", "desc": "从格鲁德山谷对岸，通过精准的悬停靴移动与跳劈回弹，成年林克可以到达放着木箱爱心的窗台，无需长钩锁。你会受到坠落伤害。"},
    "RT_GV_CHILD_TENT": {"name": "童年进入格鲁德山谷木匠帐篷", "desc": "木匠帐篷的读盘区对童年开放。"},
    "RT_GV_CHILD_CUCCO_JUMP": {"name": "格鲁德山谷栅栏跳跃（小鸡）", "desc": "童年时带着小鸡，可以跳劈越过栅栏。"},
    "RT_GV_HOOKSHOT_BRIDGE": {"name": "格鲁德山谷桥（仅钩锁）", "desc": "利用钩锁延伸与精准布位，你可以仅用钩锁穿越格鲁德山谷的断桥。"},
    "RT_PASS_GUARDS_WITH_NOTHING": {"name": "空手溜过移动的格鲁德守卫", "desc": "逻辑上通常保证你有弓或钩锁来从远处击晕他们，但每个移动中的守卫都可以通过基础移动与 AI 操控溜过去。"},
    "RT_GF_WASTELAND_GATE_SIDEHOP_SKIP": {"name": "格鲁德堡垒大门跳过（侧跳）", "desc": "你可以从塔上侧跳出边界，然后在门的另一侧再次侧跳。\n\n这对童年最简单也最有用，但成年也能这样做以跳过格鲁德坚果。"},
    "RT_GF_ADULT_SKIP_WASTELAND_GATE": {"name": "成年跳过格鲁德堡垒荒野大门", "desc": "成年时，从监狱上方借助悬停靴精准跳劈出界，即可越过那道门。\n\n这也可用于在童年无攀爬的情况下到达塔楼并放下大门。"},
    "RT_GF_WARRIOR_WITH_DIFFICULT_WEAPON": {"name": "格鲁德堡垒战士（难用武器）", "desc": "战士可以用弹弓或炸弹袋击败。"},
    "RT_GF_LEDGE_CLIP_INTO_GTG": {"name": "窗台穿模进入训练场", "desc": "成年林克可以用窗台穿模进入 Gerudo 训练场，无需格鲁德会员卡。"},
    "RT_HW_CROSSING": {"name": "无悬停靴/长钩锁穿越荒野", "desc": "你可以用特定的后退走方式穿过流沙。注意，童年跳向地毯商人通常需要相当精准的跳劈。"},
    "RT_LENS_HW": {"name": "无真相之镜穿越荒野", "desc": "通过记住路线，你可以在不使用真相之镜看 Poe 的情况下穿过荒野。反向穿过荒野的对应 trick 是“反向荒野”。"},
    "RT_HW_REVERSE": {"name": "反向荒野", "desc": "通过记住路线，你可以反向穿过荒野。注意，童年跳向地毯商人通常需要相当精准的跳劈。正向穿过荒野的对应 trick 是“无真相之镜穿越荒野”。若没有任何额外道具就要越过沙之河，还须同时开启“无悬停靴/长钩锁穿越荒野”。除非所有野外入口都被随机化，否则不会预期童年林克在格鲁德堡垒做任何事。"},
    "RT_COLOSSUS_GS": {"name": "巨像丘黄金骷髅（钩锁）", "desc": "需要一定精准度。若你杀死足够多的利弗，就能争取到更多空隙来更仔细地瞄准。"},
    "RT_DEKU_BASEMENT_GS": {"name": "德古树地下室藤蔓黄金骷髅（跳劈）", "desc": "通过精准跳劈即可击败。"},
    "RT_DEKU_B1_SKIP": {"name": "德古树地下室无弹弓（跳过 B1）", "desc": "可以用精准跳跃省去在德古树 B1 用弹弓绕路。若与“关闭森林”设置一起使用，则不会保证森林内部某处必定有弹弓。此 trick 同时适用于原版与大师任务。"},
    "RT_DEKU_B1_BOW_WEBS": {"name": "德古树地下室蛛网到哥玛（弓）", "desc": "德古树地下室所有蜘蛛网墙，成年时只需用弓隔着火把点燃即可烧掉。此 trick 只适用于通往哥玛的圆形网；两道竖直网始终在逻辑内。在藤蔓墙底部的火把旁宝箱处后空翻。精准定位后，你可以隔着火把射向圆形网的右缘。这样无需任何火源也能通关成年德古树。"},
    "RT_DEKU_B1_BACKFLIP_OVER_SPIKED_LOG": {"name": "德古树地下室后空翻越过尖刺木", "desc": "允许在原版中后空翻越过德古树地下室的尖刺木。仅当开启“随机化游泳”时相关。"},
    "RT_DEKU_MQ_COMPASS_GS": {"name": "德古树大版指南针房黄金骷髅巨石（仅铁锤）", "desc": "爬到藤蔓顶端，然后松手立即跳劈，用铁锤破坏巨石，无需生成时之歌方块。"},
    "RT_DEKU_MQ_LOG": {"name": "德古树大版滚过尖刺木", "desc": "通过翻滚短暂缩小判定框，即可越过尖刺木。成年时时机要更精准一些。"},
    "RT_DC_SCARECROW_GS": {"name": "多东戈洞窟稻草人黄金骷髅（阿摩斯像）", "desc": "你可以从阿摩斯石像上跳下，到达放着黄金骷髅的壁龛。把石像整个拖过去要花相当长时间。童年起跳到壁龛时可能有点挑剔。"},
    "RT_DC_VINES_GS": {"name": "多东戈洞窟藤蔓黄金骷髅（下方长钩锁）", "desc": "这只骷髅所歇的藤蔓是单侧碰撞。你可以从下方隔着藤蔓用长钩锁射中它，从而无需放下楼梯。"},
    "RT_DC_STAIRS_WITH_BOW": {"name": "多东戈洞窟楼梯（弓）", "desc": "可以用弓以两发恰到好处的射击击落楼梯。"},
    "RT_DC_SLINGSHOT_SKIP": {"name": "多东戈洞窟童年弹弓跳过", "desc": "通过精准的踩台，童年可以在火焰圈还在时穿过平台。开启此 trick 时，建议同时开启成年变体：“多东戈洞窟尖刺陷阱房无悬停靴跳跃”。"},
    "RT_DC_SCRUB_ROOM": {"name": "多东戈洞窟双商人房（力量）", "desc": "借助一个位置便利的方块，成年可以迅速抱着炸弹花过去，炸开挡住房间（内有两只德古商人）的泥墙。"},
    "RT_DC_HAMMER_FLOOR": {"name": "多东戈洞窟击碎 Boss 大厅地板", "desc": "多东戈之王前的可炸地板，若在正中心被击中，可用铁锤破坏。仅当开启随机化 Boss 入口，或多东戈洞窟为大版且“多东戈洞窟大版用力量点燃眼睛”的任一变体开启时相关。"},
    "RT_DC_DODONGO_CHU": {"name": "多东戈洞窟仅用炸弹袋击败多东戈", "desc": "通过精准时机，你可以在后空翻中喂多东戈之王一枚炸弹袋"},
    "RT_DC_MQ_STAIRS_WITH_ONLY_STRENGTH": {"name": "多东戈洞窟大版仅力量下楼梯", "desc": "从后方取炸弹可用来放下楼梯，无需用木棒从墙上丢炸弹。"},
    "RT_DC_MQ_CHILD_BOMBS": {"name": "多东戈洞窟大版童年早期炸弹袋区", "desc": "从上方精准跳劈，你可以仅以童年身份到达炸弹袋区，无需弹弓。你会受到坠落伤害。"},
    "RT_DC_MQ_CHILD_EYES": {"name": "多东戈洞窟大版童年用力量点燃眼睛", "desc": "若你动作极快，可以用房间顶部的炸弹花点燃眼睛。童年完成此 trick 比成年难得多。玩家还应在无爆炸物的情况下通关多东戈后方区域，包括越过阿摩斯墙去够 Boss 门的开关。"},
    "RT_DC_MQ_ADULT_EYES": {"name": "多东戈洞窟大版成年用力量点燃眼睛", "desc": "若你动作极快，可以用房间顶部的炸弹花点燃眼睛。"},
    "RT_DC_EYES_CHU": {"name": "多东戈洞窟用炸弹袋点燃眼睛", "desc": "你可以从主房间用炸弹袋点燃多东戈头部的眼睛，从而立即到达迷宫终点。"},
    "RT_JABU_BOSS_HOVER": {"name": "Jabu 近 Boss 房（悬停靴）", "desc": "当电梯在最高点时，可以抱着一只箱子后退走把它运到蓝开关处。或者，你可以从开关处迅速翻滚并在门关闭前开门，从而省去运箱子。不过时机非常紧。"},
    "RT_JABU_NEAR_BOSS_RANGED": {"name": "Jabu 近 Boss 天花板开关/黄金骷髅（无回力标或爆炸物）", "desc": "原版 Jabu：从房间入口附近，可以用精准瞄准的弹弓、弓或长钩锁击中开启 Boss 房门的开关。同样，若爬到藤蔓顶端，可以站在平台右缘隔着玻璃射击。在这个距离，连钩锁都能够到开关。此 trick 仅在开启“随机化 Boss 入口”时相关。大版 Jabu：用与在原版击中开关相同的方法，可用长钩锁取走黄金骷髅令牌。"},
    "RT_JABU_NEAR_BOSS_EXPLOSIVES": {"name": "Jabu 近 Boss 天花板开关（爆炸物）", "desc": "你可以用精准瞄准的炸弹袋击中开启 Boss 房门的开关。同样，成年可以用悬停靴向开关扔炸弹。此 trick 仅在开启“随机化 Boss 入口”时相关。"},
    "RT_JABU_B1_CUBE_HOVER": {"name": "Jabu B1 越过方块（悬停靴）", "desc": "仅用悬停靴即可到达方块另一侧的壶。"},
    "RT_LENS_JABU_MQ": {"name": "大版 Jabu 无真相之镜", "desc": "移除大版 Jabu 中对真相之镜的要求。"},
    "RT_JABU_MQ_RANG_JUMP": {"name": "大版 Jabu 指南针宝箱（回力标）", "desc": "回力标可以瞄准牛来生成宝箱：从宝箱生成的窗台起跳，于空中将回力标掷出，即可击中牛开关。"},
    "RT_JABU_MQ_SOT_GS": {"name": "大版 Jabu 时之歌方块黄金骷髅（回力标）", "desc": "让回力标穿过时之歌方块回到你手中，从而抓取令牌。"},
    "RT_JABU_BARINADE_POTS": {"name": "用壶击败 Jabu Barinade", "desc": "可以用壶对 Barinade 造成伤害，仅需回力标即可将其击败。"},
    "RT_LENS_BOTW": {"name": "无需真相之镜通关井底", "desc": "移除井底对真相之镜的要求。"},
    "RT_BOTTOM_OF_THE_WELL_NAVI_DIVE": {"name": "井底 Navi 潜水", "desc": "你需要德古木棒或科克里之剑，才能与 Navi 一起潜水进入井底。"},
    "RT_BOTW_CHILD_DEADHAND": {"name": "童年无科克里之剑击败 Dead Hand", "desc": "需要 9 根木棒或 5 次跳劈。"},
    "RT_BOTW_BASEMENT": {"name": "井底地图宝箱（力量与木棒）", "desc": "地下室的宝箱可以通过力量取得：用点燃的木棒跳劈以够到炸弹花。"},
    "RT_BOTW_PITS": {"name": "井底大版跳过深坑", "desc": "虽然井底的深坑无法靠直接跑过去跳越，但你仍可通过侧跳或后空翻越过它们。借助爆炸物，这能让你无需塞尔达摇篮曲就进入中央区域；若有塞尔达摇篮曲，则能让你无需爆炸物就进入西侧内室。"},
    "RT_BOTW_MQ_DEADHAND_KEY": {"name": "井底大版 Dead Hand 独立钥匙（回力标）", "desc": "回力标可以把物品从瓦砾中勾出，无需用爆炸物炸开。"},
    "RT_FOREST_FIRST_GS": {"name": "森林神殿首房黄金骷髅（难用武器）", "desc": "允许在从藤蔓松手时用剑或木棒跳劈杀死这只骷髅。通过向后翻滚到树上可以避免坠落伤害。也允许童年用扔炸弹将其杀死。童年用炸弹更难，因为童年林克较矮。"},
    "RT_FOREST_COURTYARD_EAST_GS": {"name": "森林神殿东庭院黄金骷髅（回力标）", "desc": "精准的回力标投掷可以让童年杀死骷髅并取走令牌。"},
    "RT_FOREST_VINES": {"name": "森林神殿东庭院藤蔓（钩锁）", "desc": "通往标准版排水井开关所在处的藤蔓，仅用钩锁就能勉强够到。大版同样适用。"},
    "RT_FOREST_COURTYARD_LEDGE": {"name": "森林神殿东北庭院窗台（悬停靴）", "desc": "凭借精准的悬停靴移动，你可以从上层阳台落到这个窗台。若足够精准，则无需承受坠落伤害。大版中这会省去长钩锁要求；原版中这能省去入口随机化里的钩锁要求。"},
    "RT_FOREST_DOORFRAME": {"name": "森林神殿东庭院门框（悬停靴）", "desc": "从这个庭院上层阳台做一次精准的悬停靴移动，可站上门框顶部。原版与大版均适用。原版中，从门框顶部可以召唤皮埃尔，让你提前进入落顶房；大版中，这让你能在无钩锁或时之歌的情况下，以成年身份取得门框上的黄金骷髅。"},
    "RT_FOREST_OUTSIDE_BACKDOOR": {"name": "森林神殿外侧后门（跳劈）", "desc": "可以用跳劈后坐力抵达方块谜题房中通往西庭院的窗台。这能省去原版里潜在的悬停靴要求，有时也适用于大版。童年与成年皆可完成。"},
    "RT_FOREST_COURTYARD_HEARTS_BOOMERANG": {"name": "森林神殿庭院爱心（回力标）", "desc": "从水边精准投掷的回力标，可以从地面够到爱心。若无法游泳，可在回力标返回时从水中后退，让爱心落到地面上。"},
    "RT_FOREST_WELL_SWIM": {"name": "用钩锁游过森林神殿水井", "desc": "尽可能低且尽可能靠右地射击井中的藤蔓，然后立即在天花板下方向右游去。这通常只在大版中有用。"},
    "RT_FOREST_MQ_BLOCK_PUZZLE": {"name": "用炸弹鼠跳过森林神殿大版方块谜题", "desc": "进入房间后，将炸弹鼠沿正中央的墙笔直向上送出。"},
    "RT_FOREST_MQ_JS_HALLWAY_SWITCH": {"name": "森林神殿大版扭曲走廊开关（跳劈）", "desc": "可以通过玻璃方块用跳劈击中扭转走廊的开关。要站到开关前方，可用悬停靴，或在房间顶部击中捷径开关后从生成的玻璃方块跳过去。童年可用木棒，但科克里之剑太短，无法穿过玻璃击中。"},
    "RT_FOREST_MQ_HOOKSHOT_HALLWAY_SWITCH": {"name": "森林神殿大版扭曲走廊开关（钩锁）", "desc": "玻璃方块与墙之间有一道很小的缝隙。透过缝隙，你可以用钩锁勾住天花板上的目标。"},
    "RT_FOREST_MQ_RANG_HALLWAY_SWITCH": {"name": "森林神殿大版扭曲走廊开关（回力标）", "desc": "回力标可以穿墙回到林克手中，让童年击中走廊开关。这可用于让成年稍后通过，或配合“森林神殿外侧后门（跳劈）”。"},
    "RT_FOREST_MQ_CHILD_DOORFRAME": {"name": "森林神殿大版门框黄金骷髅（童年无回力标）", "desc": "若成年用火之箭烧掉庭院蛛网（在 Ship 随机器中这是永久旗标），童年就能爬上阳台，从栏杆跳向时之歌方块，再从那里滚动跳或撞墙跳抵达门框。\n从那里，可以用蹲刺、爆炸物或其他远程武器杀死黄金骷髅，再通过爬下取走。"},
    "RT_FIRE_SOT": {"name": "火之神殿时之歌房黄金骷髅（无时之歌）", "desc": "可以用一次精准的跳跃抵达这个房间。"},
    "RT_FIRE_STRENGTH": {"name": "火之神殿攀爬（无力量）", "desc": "可以用一次精准跳跃省去推方块。"},
    "RT_FIRE_SCARECROW": {"name": "火之神殿东塔（无稻草人之歌）", "desc": "又称“像素射击”。长钩锁可以够到电梯本身的目标，从而让你无需生成稻草人。"},
    "RT_FIRE_SKIP_FLAME_WALLS": {"name": "火之神殿跳过火焰墙", "desc": "若动作迅速，你可以在火焰墙升起挡路之前，从它边缘溜过去。要做到不受伤则更需精准。这让你无需小钥匙或悬停靴也能推进。大版中，若开启了“火之神殿大版下→上蜥蜴迷宫（悬停靴）”或“（精准跳跃）”，这也能让你在无需钩锁的情况下更深入迷宫。\n童年可以在大版大厅侧跳越过火焰墙。"},
    "RT_FIRE_MQ_NEAR_BOSS": {"name": "火之神殿大版近 Boss 宝箱（不破坏木箱）", "desc": "火把的判定框略微伸出木箱之外。朝木箱侧面射出一支火箭，即可点燃火把，无需绕过去破坏木箱。"},
    "RT_FIRE_MQ_BLOCKED_CHEST": {"name": "火之神殿大版大熔岩房封锁门（无钩锁）", "desc": "大熔岩房中火焰墙的判定框之间存在一道缝隙。若你知道缝隙位置，就可以跳过去，省去使用钩锁。要做到不受伤则更需精准。"},
    "RT_FIRE_MQ_BK_CHEST": {"name": "火之神殿大版 Boss 钥匙宝箱（无弓）", "desc": "若你在两座火把之间迅速移动，仅用丁斯的火焰就能点燃两座计时火把，从而解除 Boss 钥匙宝箱房门的门闩。也可以利用游戏计算已点燃火把数量的疏忽，仅用丁斯的火焰解除门闩。"},
    "RT_FIRE_MQ_CLIMB": {"name": "火之神殿大版攀爬（无火源）", "desc": "你可以用悬停靴悬停到可攀爬的墙边，省去火源并生成钩锁目标。"},
    "RT_FIRE_MQ_MAZE_SIDE_ROOM": {"name": "火之神殿大版蜥蜴迷宫侧室（无木箱）", "desc": "你可以从蓝色开关走到门口，在栅栏重新关闭前迅速开门。这省去了需要到达迷宫上层、取木箱放到开关上的步骤。"},
    "RT_FIRE_MQ_MAZE_HOVERS": {"name": "火之神殿大版下→上蜥蜴迷宫（悬停靴）", "desc": "利用木箱使用悬停靴，可以爬到上层迷宫，无需生成并使用钩锁目标。"},
    "RT_FIRE_MQ_MAZE_JUMP": {"name": "火之神殿大版下→上蜥蜴迷宫（精准跳跃）", "desc": "从木箱上精准一跳，可以爬到上层迷宫，无需生成并使用钩锁目标。此 trick 取代了“火之神殿大版下→上蜥蜴迷宫（悬停靴）”与“火之神殿大版蜥蜴迷宫侧室（无木箱）”。"},
    "RT_FIRE_MQ_ABOVE_MAZE_GS": {"name": "火之神殿大版火焰墙迷宫上方黄金骷髅（下方长钩锁）", "desc": "放置这只黄金骷髅的房间地板，仅从上方才是实心的。从下方迷宫中，可以用长钩锁穿过天花板取得令牌，比正常少用两把小钥匙。"},
    "RT_WATER_LONGSHOT_TORCH": {"name": "水之殿火把长钩锁", "desc": "站在中央石柱东侧，用长钩锁击中底层的火把。游过走廊并浮到顶层。这让你无需铁靴即可进入该区域并降低水位。在水之殿中，多数能让你省去铁靴的 trick 都需先开启此 trick 才有意义。"},
    "RT_WATER_CRACKED_WALL_HOVERS": {"name": "水之殿裂缝墙（悬停靴）", "desc": "穿着悬停靴做一次空中侧跳，即可抵达裂缝墙，无需将水位升到中层。"},
    "RT_WATER_CRACKED_WALL": {"name": "水之殿裂缝墙（无额外道具）", "desc": "一次精准的跳劈（以及其他方法）可让你抵达裂缝墙，无需悬停靴，也无需将水位升到中层。此 trick 取代了“水之殿裂缝墙（悬停靴）”。"},
    "RT_WATER_BK_REGION": {"name": "水之殿 Boss 钥匙区域（悬停靴）", "desc": "凭借精准的悬停靴移动，无需长钩锁即可抵达 Boss 钥匙宝箱所在区域。无需承受尖刺伤害。随后房间中的黄金骷髅令牌也可仅用悬停靴取得。"},
    "RT_WATER_NORTH_BASEMENT_LEDGE_JUMP": {"name": "水之殿北侧地下室窗台（精准跳跃）", "desc": "在北侧地下室，有一个窗台；在原版水之殿中，巨石会从那里滚入房间。通常直接跳上这个窗台在逻辑上需要悬停靴，但通过精准跳跃，无需悬停靴也能做到。此 trick 原版与大版均适用。"},
    "RT_WATER_FW_CENTRAL_GS": {"name": "水之殿中央石柱黄金骷髅（法洛拉的疾风）", "desc": "若在中央石柱内设置法洛拉的疾风，并在将水位升到最高后回到该传送点，你就能用钩锁或回力标取得这只黄金骷髅令牌。"},
    "RT_WATER_IRONS_CENTRAL_GS": {"name": "水之殿中央石柱黄金骷髅（铁靴）", "desc": "打开通往中央石柱的中层水位门后，只要你不离开房间，门就会保持开启，即便你把水位升到了最高。待水位升高后，穿着铁靴穿过那扇门，你就能用钩锁取得黄金骷髅令牌。"},
    "RT_WATER_CENTRAL_BOW": {"name": "水之殿中央弓靶（无长钩锁或悬停靴）", "desc": "一次非常精准的弓射可以从上层地板击中眼睛开关。然后，你可以跳进走廊，在闸门关闭前通过。童年也能做到，用弹弓代替弓。"},
    "RT_WATER_HOOKSHOT_FALLING_PLATFORM_GS": {"name": "水之殿坠落平台房黄金骷髅（钩锁）", "desc": "若站在平台最边缘，仅用钩锁就能取得这只黄金骷髅。"},
    "RT_WATER_RANG_FALLING_PLATFORM_GS": {"name": "水之殿坠落平台房黄金骷髅（回力标）", "desc": "若站在平台最边缘，仅用回力标就能取得这只黄金骷髅。"},
    "RT_WATER_RIVER_GS": {"name": "水之殿河流黄金骷髅（无铁靴）", "desc": "站在河流尽头露出地面的地方，一次精准的长钩锁使用可以取得令牌。不过长钩锁通常射程不足以杀死骷髅，你得先想办法用其他方式将其杀死。"},
    "RT_WATER_DRAGON_JUMP_DIVE": {"name": "水之殿龙像跳跃潜水", "desc": "若你从蛇形河进入龙像房，可以从上方侧跳而下，无需铁靴或鳞片就进入隧道。此 trick 原版与大版均适用。原版中，你必须从上方用弓射击开关，然后在闸门关闭前迅速穿过隧道。"},
    "RT_WATER_ADULT_DRAGON": {"name": "水之殿龙像开关（成年在水平面上方）", "desc": "通常你需要钩锁和铁靴来击中开关并游过隧道以抵达宝箱。但若是站在干地上击中开关——使用炸弹鼠、钩锁或弓之一——就可能省去其中一项或两项要求。闸门打开后，除了用铁靴外，还可以借助至少银鳞片、把握时机的潜水游过隧道。若从蛇形河来，也可以用跳跃潜水进入隧道。"},
    "RT_WATER_CHILD_DRAGON": {"name": "水之殿龙像开关（童年在水平面上方）", "desc": "童年可以用炸弹鼠、弹弓或回力标之一，从干地上击中开关。然后，要抵达宝箱，童年可以借助至少银鳞片潜水穿过隧道。这次潜水的时机与定位必须完美，才能真正钻到闸门下方，而且一切都需极快完成，以便在闸门关闭前通过。务必同时开启“水之殿龙像开关（成年在水平面上方）”作为成年人的对应 trick。"},
    "RT_WATER_MQ_CENTRAL_PILLAR": {"name": "水之殿大版中央石柱（火之箭）", "desc": "倾斜的火把判定框颇具迷惑性。每当你看到一把从墙里斜伸出的火把，可以预期它的判定框大部分或全都在墙的另一侧。这让用箭点燃倾斜火把非常棘手。水之殿大版中央石柱的火把就是个尤为过分的例子。逻辑上通常预期你使用丁斯的火焰与时之歌。"},
    "RT_WATER_IRON_BOOTS_LEDGE_GRAB": {"name": "水之殿浮出水面时铁靴抓窗台", "desc": "在窗台前潜水，点按 B 加速上浮，然后在浮出时装备铁靴，即可抓住窗台爬上更高处。这可用于抵达 Boss 门前的窗台与原版指南针宝箱，或用于大版的储藏室。"},
    "RT_WATER_INVISIBLE_HOOKSHOT_TARGET": {"name": "水之殿隐形钩锁目标", "desc": "大版中可利用隐形的钩锁几何，越过挡住你提前取得这只黄金骷髅的闸门，省去一把小钥匙，也无需悬停靴或稻草人来抵达上锁的门。\n原版中这可用于无需青铜鳞片通过。"},
    "RT_WATER_MORPHA_WITHOUT_HOOKSHOT": {"name": "水之殿无钩锁击败 Morpha", "desc": "可以在没有钩锁的情况下劈砍 Morpha。"},
    "RT_LENS_SHADOW": {"name": "影子神殿静止物体（无真相之镜）", "desc": "移除影子神殿中除跨越深坑房移动平台、以及与 Bongo Bongo 战斗之外，多数区域对真相之镜的要求。"},
    "RT_LENS_SHADOW_PLATFORM": {"name": "影子神殿隐形移动平台（无真相之镜）", "desc": "移除影子神殿中，双向跨越深坑房隐形移动平台对真相之镜的要求。"},
    "RT_LENS_BONGO": {"name": "影子神殿无真相之镜击败 Bongo Bongo", "desc": "可以无需真相之镜击败 Bongo Bongo，因为那双手很好地提示了眼睛所在的位置。"},
    "RT_SHADOW_UMBRELLA_HOVER": {"name": "影子神殿石伞跳过", "desc": "从下层宝箱出发的一次非常精准的悬停靴移动，可以让你站上落下的尖刺之上，无需拉动方块。原版与大版均适用。"},
    "RT_SHADOW_UMBRELLA_CLIP": {"name": "影子神殿石伞穿模", "desc": "在落下尖刺下落时后空翻，即可从上方穿模而过，无需任何其他要求。原版与大版均适用。"},
    "RT_SHADOW_UMBRELLA_GS": {"name": "影子神殿落刺黄金骷髅（悬停靴）", "desc": "杀死骷髅后，从下层宝箱出发的一次非常精准的悬停靴移动，可以让你站上落下的尖刺，无需拉动方块。从那里，再一次非常精准的悬停靴移动可让你取得令牌，无需钩锁。原版与大版均适用。"},
    "RT_SHADOW_FREESTANDING_KEY": {"name": "影子神殿独立钥匙（炸弹鼠）", "desc": "把握时机放出炸弹鼠，让它在罐子底部附近爆炸。"},
    "RT_SHADOW_STATUE": {"name": "影子神殿河流雕像（炸弹鼠）", "desc": "让炸弹鼠绕峡谷边缘行进，即可击倒雕像，无需弓。原版与大版影子神殿均适用。"},
    "RT_SHADOW_BONGO": {"name": "影子神殿无抛射物击败 Bongo Bongo", "desc": "使用精准的剑劈，可以在不使用抛射物的情况下击败 Bongo Bongo。这仅在配合影子神殿捷径或随机化 Boss 入口时相关。"},
    "RT_LENS_SHADOW_MQ": {"name": "影子神殿大版静止物体（无真相之镜）", "desc": "移除影子神殿大版中多数区域对真相之镜的要求。例外见“影子神殿大版隐形移动平台（无真相之镜）”“影子神殿大版隐形刀刃银卢比（无真相之镜）”“影子神殿大版第二只 Dead Hand（无真相之镜）”与“影子神殿无真相之镜击败 Bongo Bongo”。"},
    "RT_LENS_SHADOW_MQ_INVISIBLE_BLADES": {"name": "影子神殿大版隐形刀刃银卢比（无真相之镜）", "desc": "移除影子神殿大版中，隐形刀刃房银卢比收集对真相之镜或娜茹之爱的要求。"},
    "RT_LENS_SHADOW_MQ_PLATFORM": {"name": "影子神殿大版隐形移动平台（无真相之镜）", "desc": "移除影子神殿大版中，双向跨越深坑房隐形移动平台对真相之镜的要求。"},
    "RT_LENS_SHADOW_MQ_DEADHAND": {"name": "影子神殿大版第二只 Dead Hand（无真相之镜）", "desc": "Dead Hand 会在房间内随机位置生成。拥有真相之镜可免去在房间里搜寻其生成位置的麻烦。"},
    "RT_SHADOW_MQ_GAP": {"name": "影子神殿大版真相旋盘缺口（长钩锁）", "desc": "你可以用长钩锁勾住火把，并跳劈后坐力落到舌头上。若从房间左侧用长钩锁勾住右侧火把，效果最佳。"},
    "RT_SHADOW_MQ_INVISIBLE_BLADES": {"name": "影子神殿大版隐形刀刃（无时之歌）", "desc": "利维利（Like Like）可以把你顶向那些通常需要时之歌才能取得的银卢比或回复爱心。由于利维利顶起的高度不足以让你在 OHKO 模式下通过，此 trick 无法在 OHKO 中使用。"},
    "RT_SHADOW_MQ_HUGE_PIT": {"name": "影子神殿大版下深坑（无火源）", "desc": "通常一个冰冻的眼睛开关会生成一些可用来爬下的平台，但实际上有一小块你可以站立的地面，直接跳下去即可。"},
    "RT_SHADOW_MQ_WINDY_WALKWAY": {"name": "影子神殿大版逆风走廊（无悬停靴）", "desc": "可以从通风走廊的壁龛跳到中间平台。有两种方法：等门对面的风扇停下并一直向前；或向右跳，被那里风扇吹向平台窗台。注意这种距离的跳跃并不稳定，但仍有可能。"},
    "RT_LENS_SPIRIT": {"name": "精神神殿（无真相之镜）", "desc": "移除精神神殿中对真相之镜的要求。"},
    "RT_SPIRIT_CHILD_CHU": {"name": "精神神殿童年侧桥（炸弹鼠）", "desc": "把握时机放出的炸弹鼠可以击中开关。"},
    "RT_SPIRIT_WEST_LEDGE": {"name": "精神神殿雕像房西窗台检查（回力标）", "desc": "小心走上雕像的上臂，即可获得一个好角度，用回力标收集黄金骷髅（原版）与最远的罐子（大版）。大版中最近的罐子可从前臂够到，始终在逻辑之内。"},
    "RT_SPIRIT_LOWER_ADULT_SWITCH": {"name": "精神神殿下层成年开关（炸弹）", "desc": "可以用炸弹击中天花板上的开关，但必须从特定距离、以精准时机投出。"},
    "RT_SPIRIT_STATUE_JUMP": {"name": "精神神殿雕像房从手部跳向上层窗台", "desc": "一次精准的跳跃，可让成年在无需悬停靴，或钩锁（原版）/时之歌（大版）的情况下取得以下物品：\n- 精神神殿雕像房东北宝箱\n- 精神神殿大厅黄金骷髅\n- 精神神殿大版中央密室左上罐子（左）\n- 精神神殿大版中央密室左上罐子（右）"},
    "RT_SPIRIT_MAP_CHEST": {"name": "精神神殿地图宝箱（弓）", "desc": "要从上层火把获得通往地图宝箱火把的视线，你必须把一座阿摩斯石像一路拖上楼梯。"},
    "RT_SPIRIT_SUN_CHEST": {"name": "精神神殿太阳方块房宝箱（弓）", "desc": "利用房间里的方块作为平台，你可以获得通往全部三座火把的视线。火把的计时很短，因此你必须迅速移动才能点燃全部三座。\n也可以用后空翻代替，无需推方块即可点燃火把。"},
    "RT_SPIRIT_WALL": {"name": "精神神殿移动墙（无额外道具）", "desc": "逻辑上通常保证你在攀爬墙之前，有办法对付光束眼与墙蜘蛛。"},
    "RT_LENS_SPIRIT_MQ": {"name": "精神神殿大版（无真相之镜）", "desc": "移除精神神殿大版中对真相之镜的要求。"},
    "RT_SPIRIT_MQ_SUN_BLOCK_SOT": {"name": "精神神殿大版太阳方块房（童年无时之歌）", "desc": "成年可以轻松直接跳到解除太阳方块房门门闩的开关，但童年林克若不生成时之歌方块作为起跳点就无法完成这一跳。你可以把木箱从上方扔到开关上来越过此限制——这确实会解除门闩，但木箱会立即碎裂，所以你必须在门重新关上前迅速通过。"},
    "RT_SPIRIT_MQ_SUN_BLOCK_GS": {"name": "精神神殿大版太阳方块房黄金骷髅（回力标）", "desc": "以让回力标弯曲穿过玻璃方块侧面的方式投出，击中黄金骷髅。"},
    "RT_SPIRIT_MQ_LOWER_ADULT": {"name": "精神神殿大版下层成年（无火之箭）", "desc": "站在精准位置，可以用单次丁斯的火焰点燃其中两座火把。这省下的时间足以让你仅用丁斯的火焰点燃全部三座火把。"},
    "RT_SPIRIT_MQ_FROZEN_EYE": {"name": "精神神殿大版冰冻眼睛开关（无火）", "desc": "你可以用箭穿过火把融化冰。要找到这次射击的视线，唯一的方法是先生成时之歌方块，然后站在它最边缘。"},
    "RT_ICE_STALAGMITE_CLIP": {"name": "冰之洞窟石笋穿模", "desc": "冰之洞窟中多数阻挡道路的石笋，都可以通过基础移动穿模越过。也适用于水之试炼。"},
    "RT_ICE_STALAGMITE_HOOKSHOT": {"name": "冰之洞窟石笋（钩锁）", "desc": "以正确方式用钩锁射击石笋也能击碎它们。也适用于水之试炼。"},
    "RT_ICE_BLOCK_GS": {"name": "冰之洞窟方块房黄金骷髅（悬停靴）", "desc": "悬停靴可让你走到骷髅前方，用跳劈将其杀死。然后，悬停靴还能再次使用来取得令牌，全程无需钩锁或回力标。"},
    "RT_ICE_MQ_RED_ICE_GS": {"name": "冰之洞窟大版红冰黄金骷髅（无时之歌）", "desc": "若侧跳到完美位置，你可以短暂站在放有红冰的平台上，刚好够时间倒一些蓝火。"},
    "RT_LENS_GTG": {"name": "格鲁德训练场（无真相之镜）", "desc": "移除格鲁德训练场中对真相之镜的要求。"},
    "RT_GTG_WITHOUT_HOOKSHOT": {"name": "格鲁德训练场左侧银卢比（无钩锁）", "desc": "收集完房间中其余银卢比后，你可以在被墙之主抓住、被拉起时够到天花板上的最后那枚银卢比。然后，你还必须在不使用钩锁的情况下离开房间。若动作迅速，你可以在火焰墙升起挡路前从它边缘溜过；要做到不受伤则更需精准。"},
    "RT_GTG_FAKE_WALL": {"name": "用悬停靴抵达格鲁德训练场假墙窗台", "desc": "从宝箱顶部一次精准的悬停靴使用，可以让你抓住窗台，无需通常的要求。大版中这总会省去时之歌要求；原版中这会省去钩锁要求，但仅当开启“格鲁德训练场左侧银卢比（无钩锁）”时才相关。"},
    "RT_GTG_LAVA_JUMP": {"name": "格鲁德训练场无道具熔岩房跳跃", "desc": "一次精准的滚动跳，可以让你在熔岩房中跳过除最远平台外的所有平台。"},
    "RT_LENS_GTG_MQ": {"name": "格鲁德训练场大版（无真相之镜）", "desc": "移除格鲁德训练场大版中对真相之镜的要求。"},
    "RT_GTG_MQ_WITH_HOOKSHOT": {"name": "格鲁德训练场大版左侧银卢比（钩锁）", "desc": "最高那枚银卢比可以通过钩锁勾住目标，然后立即朝卢比跳劈取得。"},
    "RT_GTG_MQ_WITHOUT_HOOKSHOT": {"name": "格鲁德训练场大版左侧银卢比（无钩锁）", "desc": "收集完房间中其余银卢比后，你可以在被墙之主抓住、被拉起时够到天花板上的最后那枚银卢比。墙之主不会追踪到你正位于卢比正下方。你应在墙之主开始尝试抓住你之后，再迈出最后一步站到卢比下方。此 trick 还包含：解除通往训练场最后一个宝箱的门闩的开关，可以不用抛射物、仅凭一次精准跳劈击中。此 trick 取代了“格鲁德训练场大版左侧银卢比（钩锁）”。"},
    "RT_LENS_GANON": {"name": "加农城堡（无真相之镜）", "desc": "移除加农城堡中对真相之镜的要求。"},
    "RT_GANON_SPIRIT_TRIAL_HOOKSHOT": {"name": "精神试炼（无钩锁）", "desc": "成年可以通过在阿摩斯石像上完成一次精准跳跃和一次把握时机的跳劈，取得最高的卢比。"},
    "RT_LENS_GANON_MQ": {"name": "加农城堡大版（无真相之镜）", "desc": "移除加农城堡大版中对真相之镜的要求。"},
    "RT_GANON_MQ_FIRE_TRIAL": {"name": "火之试炼大版（钩锁）", "desc": "仅用钩锁勾住火之试炼终点的目标是可能的，但需要精准瞄准与完美定位。主要难点在于要站上方尖碑的最边缘而不掉进熔岩。"},
    "RT_GANON_MQ_SHADOW_TRIAL": {"name": "影子试炼大版火把（弓）", "desc": "你可以用箭穿过房间起点处已点燃的火把，从而无需火源点燃本房间的火把。由于房间极暗、未点燃的火把又极远，要正确瞄准这一箭颇为困难。"},
    "RT_GANON_MQ_LIGHT_TRIAL": {"name": "光之试炼大版（无钩锁）", "desc": "若动作迅速，你可以在火焰墙升起挡路前从它边缘溜过。这种情况下要做到不受伤尤其需要精准。"},
}
